cards.solution:
function buatSlug(judul) {
  return judul.trim().toLowerCase().replaceAll(" ", "-");
}
function adaKata(teks, kata) {
  return teks.toLowerCase().includes(kata.toLowerCase());
}
console.log(buatSlug("  Belajar JS Dasar "));
console.log(buatSlug("Java OOP"));
console.log(adaKata("Belajar JavaScript", "script"));
console.log(adaKata("Belajar Java", "python"));
